 * to prevent excessive URL length.
 *
 * @param subdomain The subdomain prefix to validate.
 * @return true if the subdomain is valid, false otherwise.
 */
static bool is_valid_subdomain(const char* subdomain) {
    if (subdomain == NULL || strlen(subdomain) == 0) {
        return false;
    }

    // Check for leading/trailing dots and consecutive dots
    if (subdomain[0] == '.' || subdomain[strlen(subdomain) - 1] == '.') {
        return false;
    }
    for (size_t i = 0; i < strlen(subdomain) - 1; ++i) {
        if (subdomain[i] == '.' && subdomain[i+1] == '.') {
            return false;
        }
    }

    // Basic check for characters that are generally not allowed in subdomains.
    // This is not exhaustive but covers common problematic characters.
    const char* invalid_chars = " /\\:*?\"<>|";
    for (size_t i = 0; i < strlen(subdomain); ++i) {
        for (size_t j = 0; j < strlen(invalid_chars); ++j) {
            if (subdomain[i] == invalid_chars[j]) {
                return false;
            }
        }
    }

    // Check if the subdomain part itself is too long to fit in the URL
    // "https://." + subdomain + "." + domain
    if (strlen("https://.") + strlen(subdomain) + strlen(".") + strlen(domain) + 1 > MAX_URL_LENGTH) {
        return false;
    }

    return true;
}

